"""navera_lite/geo.py — positions on the Earth: sphere, WGS84 ellipsoid, ECEF and ENU. Part of NAVERA Lite,
the course's teaching stack (mission 06). Written for the course; it is not NAVERA code.

Conventions (courses/_lib/CONVENTIONS.md): angles in degrees at the interface, radians only inside
trigonometric calls; latitude before longitude; distances and heights in metres; heights above the
WGS84 ellipsoid; bearings clockwise from true north in [0, 360).
"""
import math

import numpy as np

EARTH_RADIUS_M = 6_371_000.0          # mean radius of the sphere used by every "sphere" function below

WGS84_A = 6_378_137.0                 # semi-major axis (equatorial radius), m — exact by definition
WGS84_F = 1.0 / 298.257223563         # flattening f = (a − b) / a — exact by definition
WGS84_B = WGS84_A * (1.0 - WGS84_F)   # semi-minor axis (polar radius) = 6 356 752.314 m
WGS84_E2 = WGS84_F * (2.0 - WGS84_F)  # first eccentricity squared = 0.00669438


# from mission 06 — finished: read it, use it, do not change it
def is_finite_latlon(lat, lon):
    """True for a usable position: two finite numbers, latitude in [−90, 90], longitude in [−180, 180],
    and not exactly (0, 0) — "Null Island", where missing coordinates land.

    Example: is_finite_latlon(35.83, 10.64) → True;  is_finite_latlon(0.0, 0.0) → False
    """
    values = []
    for v in (lat, lon):
        if isinstance(v, bool) or not isinstance(v, (int, float, np.floating, np.integer)):
            return False
        values.append(float(v))
    la, lo = values
    finite = math.isfinite(la) and math.isfinite(lo)
    in_range = finite and abs(la) <= 90.0 and abs(lo) <= 180.0
    null_island = la == 0.0 and lo == 0.0
    return in_range and not null_island


# ====================================================================== the sphere (session 1)

# from mission 06 — finished: read it, use it, do not change it
def enu_flat(lat0, lon0, lat, lon):
    """Flat-Earth shortcut: how many metres east and north of (lat0, lon0) the point (lat, lon) is,
    on the sphere of radius EARTH_RADIUS_M, with the scale of the parallel taken at the MEAN latitude
    of the two points. Works across the ±180° meridian (the shortest way round in longitude).

    Inputs: degrees. Returns (e_m, n_m), two floats in metres.
    Example: enu_flat(51.5074, -0.1278, 48.8566, 2.3522) → (about 176 585.4, about −294 755.5)
             (Paris seen from London: 177 km east, 295 km south)
    """
    dlon = (lon - lon0 + 180.0) % 360.0 - 180.0
    mean_lat = math.radians((lat0 + lat) / 2.0)
    e = math.radians(dlon) * EARTH_RADIUS_M * math.cos(mean_lat)
    n = math.radians(lat - lat0) * EARTH_RADIUS_M
    return e, n


# from mission 06 — finished: read it, use it, do not change it
def offset(lat, lon, e_m, n_m):
    """The inverse of enu_flat: the point e_m metres east and n_m metres north of (lat, lon).
    enu_flat(lat, lon, *offset(lat, lon, e, n)) gives back (e, n) exactly (to rounding).

    Inputs: degrees and metres. Returns (lat, lon) in degrees; the longitude is brought back into
    [−180, 180) (lesson §1), so 5 km east of λ = 179.99° comes out near −179.96°.
    Example: offset(-33.9249, 18.4241, 1000.0, 2000.0) → (about −33.906914, about 18.434937)
             (1 km east and 2 km north of Cape Town)
    """
    lat2 = lat + math.degrees(n_m / EARTH_RADIUS_M)
    mean_lat = math.radians((lat + lat2) / 2.0)
    lon2 = lon + math.degrees(e_m / (EARTH_RADIUS_M * math.cos(mean_lat)))
    lon2 = (lon2 + 180.0) % 360.0 - 180.0
    return lat2, lon2


