def haversine_m(lat1, lon1, lat2, lon2):
    """Great-circle distance in metres between two points on the sphere of radius EARTH_RADIUS_M.
    Works on plain numbers AND on numpy arrays (element by element, with broadcasting).

    Inputs: degrees. Returns metres (a float, or an array for array inputs).
    Example: haversine_m(51.5074, -0.1278, 48.8566, 2.3522) → about 343 556.1   (London → Paris)
             haversine_m(np.array([0.0, 0.0]), 0.0, 0.0, np.array([1.0, 90.0])) → about [111 194.9, 10 007 543.4]
    """
    p1, p2 = np.radians(lat1), np.radians(lat2)
    a = np.sin((p2 - p1) / 2.0) ** 2 + np.cos(p1) * np.cos(p2) * np.sin(np.radians(lon2 - lon1) / 2.0) ** 2
    d = 2.0 * EARTH_RADIUS_M * np.arcsin(np.sqrt(np.minimum(1.0, a)))
    return float(d) if np.ndim(d) == 0 else d


