def bearing_deg(lat1, lon1, lat2, lon2):
    """Initial bearing of the great circle from point 1 to point 2: the direction to fly at the start,
    in degrees clockwise from true north, in [0, 360).

    Inputs: degrees. Returns degrees.
    Example: bearing_deg(51.5074, -0.1278, 48.8566, 2.3522) → about 148.12   (London → Paris: south-east)
    """
    p1, p2 = math.radians(lat1), math.radians(lat2)
    dl = math.radians(lon2 - lon1)
    east = math.sin(dl) * math.cos(p2)
    north = math.cos(p1) * math.sin(p2) - math.sin(p1) * math.cos(p2) * math.cos(dl)
    return math.degrees(math.atan2(east, north)) % 360.0


# from mission 06 — finished: read it, use it, do not change it
def great_circle_points(p1, p2, n):
    """n points equally spaced along the great circle from p1 to p2 (the shortest path on the sphere):
    the first is p1, the last is p2. p1 and p2 are (lat, lon) tuples in degrees; n ≥ 2.
    Raises ValueError if n < 2 or if the points are (almost) opposite on the Earth (no unique path).

    Returns a list of n (lat, lon) tuples in degrees.
    Example: great_circle_points((0.0, 0.0), (0.0, 90.0), 3) → [(0.0, 0.0), (0.0, 45.0), (0.0, 90.0)]
             great_circle_points((51.5074, -0.1278), (48.8566, 2.3522), 3)[1] → about (50.1886, 1.1466)
    """
    if n < 2:
        raise ValueError(f"n must be at least 2, got {n}")
    a = unit_vector(*p1)
    b = unit_vector(*p2)
    cos_d = max(-1.0, min(1.0, float(a @ b)))
    d = math.acos(cos_d)
    if d < 1e-12:
        return [(float(p1[0]), float(p1[1]))] * n
    if math.pi - d < 1e-9:
        raise ValueError("the two points are opposite on the Earth: every great circle through them is as short")
    out = []
    for k in range(n):
        f = k / (n - 1)
        v = (math.sin((1.0 - f) * d) * a + math.sin(f * d) * b) / math.sin(d)
        lat = math.degrees(math.atan2(v[2], math.hypot(v[0], v[1])))
        lon = math.degrees(math.atan2(v[1], v[0]))
        out.append((lat, lon))
    out[0], out[-1] = (float(p1[0]), float(p1[1])), (float(p2[0]), float(p2[1]))
    return out


